import 'package:flutter/widgets.dart';

/// Launch languages (CORE-008) plus the RTL locales verified for layout.
const List<String> appLanguageTags = [
  'en',
  'pt-BR',
  'es',
  'hi',
  'id',
  'de',
  'fr',
  'ja',
  'ru',
  'tr',
  'zh-Hans',
  'it',
  'ar',
  'he',
];

/// Pseudo-locales generated by `tools/l10n/merge_arb.dart` for tests and
/// debug builds: expanded accented strings (en-XA) and right-to-left
/// (ar-XB). Never offered in the language picker.
const Locale pseudoExpanded = Locale('en', 'XA');
const Locale pseudoRtl = Locale('ar', 'XB');

bool isPseudoLocale(Locale l) => l.countryCode == 'XA' || l.countryCode == 'XB';

/// Each language's own name. These are data, not UI copy: a language is
/// always listed in itself so people can find their own.
String languageEndonym(String tag) => switch (tag) {
  'en' => 'English',
  'pt-BR' => 'Português (Brasil)',
  'es' => 'Español',
  'hi' => 'हिन्दी',
  'id' => 'Bahasa Indonesia',
  'de' => 'Deutsch',
  'fr' => 'Français',
  'ja' => '日本語',
  'ru' => 'Русский',
  'tr' => 'Türkçe',
  'zh-Hans' => '简体中文',
  'it' => 'Italiano',
  'ar' => 'العربية',
  'he' => 'עברית',
  _ => tag,
};

/// Parses `pt-BR` / `zh-Hans` into a [Locale]; empty means system.
Locale? localeFromTag(String tag) {
  if (tag.isEmpty) return null;
  final parts = tag.split('-');
  if (parts.length == 1) return Locale(parts[0]);
  final second = parts[1];
  return second.length == 4
      ? Locale.fromSubtags(languageCode: parts[0], scriptCode: second)
      : Locale(parts[0], second);
}
